performance.source:
[Module load: #time]; [Module load: #repl]; [Repl wrapStdio];
[[|
let failures := [0 asCell];
[System gc]; let facts := [db retainedFactCount]; let start := [16 clockNanos];
[1 to: 20 do: [:i |
  [[[Repl consoleHostInitNoConfig] isError] ifTrue: [| [failures inc]]];
  [[[Repl consoleDone] isError] ifTrue: [| [failures inc]]]
]];
[System println: [[16 clockNanos] - start]];
[System println: [[failures value] = 0]];
[System println: [[db retainedFactCount] - facts]]
] value]

setup_isolation.source:
[Module load: #time]; [Module load: #repl]; [Repl wrapStdio];
[[|
let session := [Repl clone];
// Diagnostic only: the real wrappers are already installed above. Replace only
// this instance's setup hook, leaving actual stdio, allocation and cleanup live.
[Reflect defineMethod: #wrapStdio on: session as: [:self | self]];
let failures := [0 asCell];
[System gc]; let facts := [db retainedFactCount]; let start := [16 clockNanos];
[1 to: 20 do: [:i |
  [[[session consoleHostInitNoConfig] isError] ifTrue: [| [failures inc]]];
  [[[session consoleDone] isError] ifTrue: [| [failures inc]]]
]];
[System println: [[16 clockNanos] - start]];
[System println: [[failures value] = 0]];
[System println: [[db retainedFactCount] - facts]]
] value]

probe.source:
[Alien wrap: "dlopen" signature: "p p i" as: #probeOpenProcess: on: ForeignAddress];
[Alien wrap: "dlsym" signature: "p p s" as: #probeSymbol: on: ForeignAddress];
[Alien wrap: "dlclose" signature: "i p" as: #probeCloseLibrary on: ForeignAddress];
[Alien wrap: "fileno" signature: "i p" as: #probeDescriptor on: ForeignAddress];
[[|
let library := [ForeignAddress probeOpenProcess: 1];
let input := [library probeSymbol: "__stdinp"];
let input := [[input isNull] ifTrue: [| [library probeSymbol: "stdin"]] ifFalse: [| input]];
let error := [library probeSymbol: "__stderrp"];
let error := [[error isNull] ifTrue: [| [library probeSymbol: "stderr"]] ifFalse: [| error]];
[System println: [[input isNull] not]];
[System println: [[error isNull] not]];
let inputFile := [input peekPtrAt: 0]; let errorFile := [error peekPtrAt: 0];
[System println: [[inputFile probeDescriptor] = 0]];
[System println: [[errorFile probeDescriptor] = 2]];
[System println: [[library probeCloseLibrary] = 0]];
[System println: [[inputFile probeDescriptor] = 0]];
[System println: [[errorFile probeDescriptor] = 2]]
] value]
